-- KOJAC LMS — Kanji JLPT N4 activation data
-- Migration 014: 154 additional N4 kanji after the frozen KOJAC N5 set.
-- Incremental only. Reuses learning_items + generic Kanji engine/SRS.
-- No table/RPC/RLS changes. Does not modify N5 rows or user progress.
-- Dataset is a practical teaching set informed by common JLPT N4 study lists;
-- it is not presented as an official immutable JLPT list.

begin;

-- Fail fast if the project baseline is not the expected KOJAC schema.
do $preflight$
declare
  v_n5_count integer;
  v_overlap integer;
begin
  if to_regclass('public.learning_items') is null then
    raise exception 'KOJAC N4 preflight: public.learning_items tidak ditemukan.';
  end if;

  if not exists (
    select 1 from information_schema.columns
    where table_schema='public' and table_name='learning_items' and column_name='jlpt_level'
  ) then
    raise exception 'KOJAC N4 preflight: kolom learning_items.jlpt_level tidak ditemukan.';
  end if;

  select count(*) into v_n5_count
  from public.learning_items as li
  where li.item_type='kanji' and li.jlpt_level='N5' and li.is_published=true and li.reading is null;

  if v_n5_count < 90 then
    raise exception 'KOJAC N4 preflight: baseline N5 belum lengkap (ditemukan % published Kanji N5).', v_n5_count;
  end if;

  -- N4 additions must never reuse a single-kanji record already assigned to another level.
  select count(*) into v_overlap
  from public.learning_items as li
  where li.item_type='kanji'
    and li.reading is null
    and li.prompt in ('会','同','事','自','社','発','者','地','業','方','場','員','立','開','力','問','代','明','動','京','通','言','理','体','田','主','題','意','不','作','用','度','強','公','持','野','以','思','家','世','正','院','心','界','教','元','重','近','考','画','海','売','知','道','集','別','物','使','品','計','死','特','私','始','朝','運','終','台','広','住','無','真','有','町','料','工','建','空','急','止','送','切','転','研','究','楽','起','着','店','病','質','待','試','族','銀','早','映','親','験','英','医','仕','去','味','写','答','夜','音','注','帰','歌','悪','図','週','室','歩','風','紙','黒','花','春','赤','青','館','屋','色','走','秋','夏','習','駅','洋','旅','服','夕','借','曜','肉','貸','堂','鳥','飯','勉','冬','昼','茶','弟','牛','魚','兄','犬','妹','姉','漢')
    and li.jlpt_level is distinct from 'N4';

  if v_overlap <> 0 then
    raise exception 'KOJAC N4 preflight: ditemukan % kandidat N4 yang sudah dimiliki level lain. Migration dibatalkan agar N5 tidak berubah.', v_overlap;
  end if;
end
$preflight$;

