  ('kanji','N4','漢',null,'Kanji / Tiongkok (dalam kata majemuk)',null,'{"sort_order":154,"category":"Bahasa","onyomi":["カン"],"kunyomi":[],"stroke_count":13,"examples":[{"word":"漢字","reading":"かんじ","romaji":"kanji","meaning_id":"Kanji"},{"word":"漢語","reading":"かんご","romaji":"kango","meaning_id":"kosakata Sino-Jepang"}],"sentences":[{"japanese":"漢字を毎日練習します。","reading":"かんじを まいにち れんしゅうします。","meaning":"Saya berlatih Kanji setiap hari."},{"japanese":"漢語の意味を調べます。","reading":"かんごの いみを しらべます。","meaning":"Saya mencari arti kosakata Sino-Jepang."}],"related_kanji":[{"kanji":"問","relation":"concept_related","note":"Satu tema pembelajaran: Bahasa.","meaning":"pertanyaan / menanyakan","level":"N4"},{"kanji":"言","relation":"concept_related","note":"Satu tema pembelajaran: Bahasa.","meaning":"mengatakan / kata","level":"N4"},{"kanji":"画","relation":"concept_related","note":"Satu tema pembelajaran: Bahasa.","meaning":"gambar / rencana / film","level":"N4"}],"mnemonic":{"kind":"learning_mnemonic","components":[],"tip":"Cara mudah mengingat: hubungkan 「漢」 dengan arti “Kanji / Tiongkok (dalam kata majemuk)”. Gunakan 「漢字」 (Kanji) sebagai jangkar ingatan saat melihat bentuk ini."},"curriculum":"KOJAC Kanji Core","dataset":"N4-v1","sentence_dataset":"N4-v1","learning_aids_dataset":"N4-v1","curriculum_note":"Practical N4 teaching set; not an official immutable JLPT kanji list."}'::jsonb,true)
on conflict (item_type, prompt, (coalesce(reading, '')))
do nothing;

-- Validation: exact N4 additions, complete metadata, no N5 duplication.
do $validate$
declare
  v_count integer;
  v_orders integer;
  v_bad integer;
  v_overlap integer;
  v_examples_bad integer;
  v_sentences_bad integer;
  v_relations_bad integer;
begin
  select count(*) into v_count
  from public.learning_items as li
  where li.item_type='kanji' and li.jlpt_level='N4' and li.reading is null and li.prompt in ('会','同','事','自','社','発','者','地','業','方','場','員','立','開','力','問','代','明','動','京','通','言','理','体','田','主','題','意','不','作','用','度','強','公','持','野','以','思','家','世','正','院','心','界','教','元','重','近','考','画','海','売','知','道','集','別','物','使','品','計','死','特','私','始','朝','運','終','台','広','住','無','真','有','町','料','工','建','空','急','止','送','切','転','研','究','楽','起','着','店','病','質','待','試','族','銀','早','映','親','験','英','医','仕','去','味','写','答','夜','音','注','帰','歌','悪','図','週','室','歩','風','紙','黒','花','春','赤','青','館','屋','色','走','秋','夏','習','駅','洋','旅','服','夕','借','曜','肉','貸','堂','鳥','飯','勉','冬','昼','茶','弟','牛','魚','兄','犬','妹','姉','漢');
  if v_count <> 154 then
    raise exception 'KOJAC N4 validation failed: expected 154 N4 additions, found %.', v_count;
  end if;

  select count(distinct (li.extra->>'sort_order')::integer) into v_orders
  from public.learning_items as li
  where li.item_type='kanji' and li.jlpt_level='N4' and li.reading is null and li.prompt in ('会','同','事','自','社','発','者','地','業','方','場','員','立','開','力','問','代','明','動','京','通','言','理','体','田','主','題','意','不','作','用','度','強','公','持','野','以','思','家','世','正','院','心','界','教','元','重','近','考','画','海','売','知','道','集','別','物','使','品','計','死','特','私','始','朝','運','終','台','広','住','無','真','有','町','料','工','建','空','急','止','送','切','転','研','究','楽','起','着','店','病','質','待','試','族','銀','早','映','親','験','英','医','仕','去','味','写','答','夜','音','注','帰','歌','悪','図','週','室','歩','風','紙','黒','花','春','赤','青','館','屋','色','走','秋','夏','習','駅','洋','旅','服','夕','借','曜','肉','貸','堂','鳥','飯','勉','冬','昼','茶','弟','牛','魚','兄','犬','妹','姉','漢');
  if v_orders <> 154 then
    raise exception 'KOJAC N4 validation failed: sort_order harus unik untuk 154 item.';
  end if;

  select count(*) into v_bad
  from public.learning_items as li
  where li.item_type='kanji' and li.jlpt_level='N4' and li.reading is null and li.prompt in ('会','同','事','自','社','発','者','地','業','方','場','員','立','開','力','問','代','明','動','京','通','言','理','体','田','主','題','意','不','作','用','度','強','公','持','野','以','思','家','世','正','院','心','界','教','元','重','近','考','画','海','売','知','道','集','別','物','使','品','計','死','特','私','始','朝','運','終','台','広','住','無','真','有','町','料','工','建','空','急','止','送','切','転','研','究','楽','起','着','店','病','質','待','試','族','銀','早','映','親','験','英','医','仕','去','味','写','答','夜','音','注','帰','歌','悪','図','週','室','歩','風','紙','黒','花','春','赤','青','館','屋','色','走','秋','夏','習','駅','洋','旅','服','夕','借','曜','肉','貸','堂','鳥','飯','勉','冬','昼','茶','弟','牛','魚','兄','犬','妹','姉','漢')
    and (
      coalesce(li.meaning_id,'')=''
      or coalesce(li.extra->>'category','')=''
      or jsonb_typeof(li.extra->'onyomi') is distinct from 'array'
      or jsonb_typeof(li.extra->'kunyomi') is distinct from 'array'
      or coalesce((li.extra->>'stroke_count')::integer,0)<=0
      or jsonb_typeof(li.extra->'examples') is distinct from 'array'
      or jsonb_typeof(li.extra->'sentences') is distinct from 'array'
      or jsonb_typeof(li.extra->'related_kanji') is distinct from 'array'
      or jsonb_typeof(li.extra->'mnemonic') is distinct from 'object'
    );
  if v_bad <> 0 then
    raise exception 'KOJAC N4 validation failed: % row(s) memiliki metadata inti tidak lengkap.', v_bad;
  end if;

  select count(*) into v_examples_bad
  from public.learning_items as li
  where li.item_type='kanji' and li.jlpt_level='N4' and li.reading is null and li.prompt in ('会','同','事','自','社','発','者','地','業','方','場','員','立','開','力','問','代','明','動','京','通','言','理','体','田','主','題','意','不','作','用','度','強','公','持','野','以','思','家','世','正','院','心','界','教','元','重','近','考','画','海','売','知','道','集','別','物','使','品','計','死','特','私','始','朝','運','終','台','広','住','無','真','有','町','料','工','建','空','急','止','送','切','転','研','究','楽','起','着','店','病','質','待','試','族','銀','早','映','親','験','英','医','仕','去','味','写','答','夜','音','注','帰','歌','悪','図','週','室','歩','風','紙','黒','花','春','赤','青','館','屋','色','走','秋','夏','習','駅','洋','旅','服','夕','借','曜','肉','貸','堂','鳥','飯','勉','冬','昼','茶','弟','牛','魚','兄','犬','妹','姉','漢')
    and (jsonb_array_length(li.extra->'examples') < 2 or jsonb_array_length(li.extra->'examples') > 4);
  if v_examples_bad <> 0 then
    raise exception 'KOJAC N4 validation failed: % row(s) tidak memiliki 2–4 contoh kosakata.', v_examples_bad;
  end if;

  select count(*) into v_sentences_bad
  from public.learning_items as li
  where li.item_type='kanji' and li.jlpt_level='N4' and li.reading is null and li.prompt in ('会','同','事','自','社','発','者','地','業','方','場','員','立','開','力','問','代','明','動','京','通','言','理','体','田','主','題','意','不','作','用','度','強','公','持','野','以','思','家','世','正','院','心','界','教','元','重','近','考','画','海','売','知','道','集','別','物','使','品','計','死','特','私','始','朝','運','終','台','広','住','無','真','有','町','料','工','建','空','急','止','送','切','転','研','究','楽','起','着','店','病','質','待','試','族','銀','早','映','親','験','英','医','仕','去','味','写','答','夜','音','注','帰','歌','悪','図','週','室','歩','風','紙','黒','花','春','赤','青','館','屋','色','走','秋','夏','習','駅','洋','旅','服','夕','借','曜','肉','貸','堂','鳥','飯','勉','冬','昼','茶','弟','牛','魚','兄','犬','妹','姉','漢')
    and (jsonb_array_length(li.extra->'sentences') < 2 or jsonb_array_length(li.extra->'sentences') > 4);
  if v_sentences_bad <> 0 then
    raise exception 'KOJAC N4 validation failed: % row(s) tidak memiliki 2–4 contoh kalimat.', v_sentences_bad;
  end if;

  select count(*) into v_relations_bad
  from public.learning_items as li
  cross join lateral jsonb_array_elements(li.extra->'related_kanji') as rel
  where li.item_type='kanji' and li.jlpt_level='N4' and li.reading is null and li.prompt in ('会','同','事','自','社','発','者','地','業','方','場','員','立','開','力','問','代','明','動','京','通','言','理','体','田','主','題','意','不','作','用','度','強','公','持','野','以','思','家','世','正','院','心','界','教','元','重','近','考','画','海','売','知','道','集','別','物','使','品','計','死','特','私','始','朝','運','終','台','広','住','無','真','有','町','料','工','建','空','急','止','送','切','転','研','究','楽','起','着','店','病','質','待','試','族','銀','早','映','親','験','英','医','仕','去','味','写','答','夜','音','注','帰','歌','悪','図','週','室','歩','風','紙','黒','花','春','赤','青','館','屋','色','走','秋','夏','習','駅','洋','旅','服','夕','借','曜','肉','貸','堂','鳥','飯','勉','冬','昼','茶','弟','牛','魚','兄','犬','妹','姉','漢')
    and (
      coalesce(rel->>'kanji','')=''
      or rel->>'kanji'=li.prompt
      or coalesce(rel->>'note','')=''
      or coalesce(rel->>'relation','') not in ('same_radical','similar_shape','shared_component','concept_related')
    );
  if v_relations_bad <> 0 then
    raise exception 'KOJAC N4 validation failed: % related-kanji entry tidak valid.', v_relations_bad;
  end if;

  select count(*) into v_overlap
  from public.learning_items as n4
  join public.learning_items as n5
    on n5.item_type='kanji' and n5.jlpt_level='N5' and n5.reading is null and n5.prompt=n4.prompt
  where n4.item_type='kanji' and n4.jlpt_level='N4' and n4.reading is null and n4.prompt in ('会','同','事','自','社','発','者','地','業','方','場','員','立','開','力','問','代','明','動','京','通','言','理','体','田','主','題','意','不','作','用','度','強','公','持','野','以','思','家','世','正','院','心','界','教','元','重','近','考','画','海','売','知','道','集','別','物','使','品','計','死','特','私','始','朝','運','終','台','広','住','無','真','有','町','料','工','建','空','急','止','送','切','転','研','究','楽','起','着','店','病','質','待','試','族','銀','早','映','親','験','英','医','仕','去','味','写','答','夜','音','注','帰','歌','悪','図','週','室','歩','風','紙','黒','花','春','赤','青','館','屋','色','走','秋','夏','習','駅','洋','旅','服','夕','借','曜','肉','貸','堂','鳥','飯','勉','冬','昼','茶','弟','牛','魚','兄','犬','妹','姉','漢');
  if v_overlap <> 0 then
    raise exception 'KOJAC N4 validation failed: % duplicate prompt ditemukan antara N4 dan N5.', v_overlap;
  end if;
end
$validate$;

commit;
